/* v0.7.5 文件与店铺确认修复：可反复改选店铺 + SPU历史店铺归属冲突检查 */
(function(){
function storeConflictInfoForBookV075(book,store){store=String(store||'').trim();const seen=new Set(),conflicts=[];if(!book||!store)return conflicts;for(const r of book.rows||[]){const spu=String(r?.spu||'').trim();if(!spu||seen.has(spu))continue;seen.add(spu);const historical=historyStoresForSpu(spu);if(!historical.length)continue;if(historical.length!==1||historical[0]!==store)conflicts.push({spu,current:store,historical,kind:historical.includes(store)?'duplicate':'mismatch'})}return conflicts}
function updateBookStoreConflictUIV075(i){const b=state.allBooks[i],row=document.querySelector(`#fileList .file-item [data-store-i="${i}"]`)?.closest('.file-item');if(!b||!row)return[];const badge=row.querySelector('[data-store-conflict]'),store=String(b.storeName||'').trim(),items=storeConflictInfoForBookV075(b,store);if(!badge)return items;if(!store||!items.length){badge.className='store-conflict-badge';badge.textContent='';badge.removeAttribute('title');return items}const mismatches=items.filter(x=>x.kind==='mismatch').length,dupes=items.length-mismatches;badge.className='store-conflict-badge show'+(!mismatches&&dupes?' duplicate':'');badge.textContent=mismatches?`历史归属冲突 ${items.length} 个`:`历史重复归属 ${items.length} 个`;badge.title=items.slice(0,12).map(x=>`${x.spu}：当前 ${x.current}；历史 ${x.historical.join(' / ')}`).join('\n')+(items.length>12?`\n…另有 ${items.length-12} 个`:'');return items}
function collectSelectedStoreConflictsV075(selected){const out=[];for(const b of selected)out.push(...storeConflictInfoForBookV075(b,b.storeName).map(x=>({...x,file:b.name})));const currentOwners=new Map();for(const b of selected){const store=String(b.storeName||'').trim();for(const spu of new Set((b.rows||[]).map(r=>String(r?.spu||'').trim()).filter(Boolean))){if(!currentOwners.has(spu))currentOwners.set(spu,new Set());currentOwners.get(spu).add(store)}}for(const[spu,stores]of currentOwners)if(stores.size>1)out.push({spu,current:Array.from(stores).join(' / '),historical:[],kind:'current-duplicate',file:'当前待确认文件'});return out}
function syncStorePickerV075(select,input,book,i){const value=String(input.value||'').trim();book.storeName=value;const exact=Array.from(select.options).find(o=>o.value===value&&o.value!=='__manual__');select.value=exact?exact.value:(value?'__manual__':'');updateBookStoreConflictUIV075(i)}
window.renderFileConfirm=function(){const totalRows=state.allBooks.reduce((n,b)=>n+b.rows.length,0),spus=new Set(state.allBooks.flatMap(b=>b.rows.map(r=>r.spu)));$('fileName').textContent=`已读取 ${state.allBooks.length} 个Excel文件`;$('fileName').className='hint ok';$('stats').classList.remove('hidden');$('stats').innerHTML=`<span class="pill">文件 <b>${state.allBooks.length}</b></span><span class="pill">唯一SPU <b>${spus.size}</b></span><span class="pill">价格记录 <b>${totalRows}</b></span><span class="pill">库存记录 <b>${state.allBooks.reduce((n,b)=>n+(b.inventoryRows?.length||0),0)}</b></span><span class="pill">历史SPU <b>${state.history.size}</b></span><span class="pill">历史店铺 <b>${state.storeNames.length}</b></span>`;$('loadMsg').textContent=(state.books.length?'新增表格读取成功：可随时改选店铺；系统会实时检查SPU历史店铺归属冲突。':'读取成功，请确认店铺名称；已有店铺可反复切换，也可手动输入新店铺；系统会检查SPU历史归属冲突。');$('loadMsg').className='hint ok';const sortedStores=Array.from(new Set(state.storeNames||[])).sort((a,b)=>a.localeCompare(b,undefined,{numeric:true})),box=$('fileList');box.innerHTML='';state.allBooks.forEach((b,i)=>{const d=document.createElement('div');d.className='file-item';d.tabIndex=0;d.setAttribute('role','checkbox');const options=sortedStores.map(x=>`<option value="${escapeHtml(x)}" ${b.storeName===x?'selected':''}>${escapeHtml(x)}</option>`).join(''),hasKnown=sortedStores.includes(String(b.storeName||''));d.innerHTML=`<input type="checkbox" data-i="${i}" ${b.selected===false?'':'checked'}><span class="file-name" title="${escapeHtml(b.name)}">${escapeHtml(b.name)}</span><div class="store-picker"><select class="store-history-select" data-store-select-i="${i}" aria-label="选择已有店铺"><option value="">选择已有店铺…</option>${options}<option value="__manual__" ${b.storeName&&!hasKnown?'selected':''}>＋ 手动输入/新店铺</option></select><input class="store-input" data-store-i="${i}" placeholder="店铺名称" value="${escapeHtml(b.storeName||'')}"></div><span class="store-conflict-badge" data-store-conflict></span><span class="pill">${new Set(b.rows.map(r=>r.spu)).size} SPU · ${b.rows.length} 条</span><button class="remove-file-btn" type="button" data-remove-i="${i}">移除</button>`;const ck=d.querySelector('input[type=checkbox]'),storeInp=d.querySelector('.store-input'),storeSelect=d.querySelector('.store-history-select'),removeBtn=d.querySelector('.remove-file-btn');const sync=()=>{b.selected=!!ck.checked;d.setAttribute('aria-checked',ck.checked?'true':'false');updateFileSelectionUI()};ck.addEventListener('change',sync);d.addEventListener('click',e=>{if(e.target.closest('.store-picker')||e.target.closest('.store-conflict-badge')||e.target.closest('.remove-file-btn')||e.target.closest('input[type=checkbox]'))return;ck.checked=!ck.checked;sync()});d.addEventListener('keydown',e=>{if((e.key===' '||e.key==='Enter')&&!e.target.closest('.store-picker')&&!e.target.closest('.remove-file-btn')){e.preventDefault();ck.checked=!ck.checked;sync()}});storeSelect.addEventListener('change',()=>{if(storeSelect.value==='__manual__'){storeInp.focus();storeInp.select();return}storeInp.value=storeSelect.value;b.storeName=storeSelect.value;updateBookStoreConflictUIV075(i)});storeInp.addEventListener('input',()=>syncStorePickerV075(storeSelect,storeInp,b,i));storeInp.addEventListener('change',()=>syncStorePickerV075(storeSelect,storeInp,b,i));removeBtn.onclick=async e=>{e.stopPropagation();await removePendingBook(i)};box.appendChild(d);updateBookStoreConflictUIV075(i)});updateFileSelectionUI();requestAnimationFrame(()=>{$('taskFileConfirmGrid')?.scrollIntoView({behavior:'smooth',block:'nearest'})})};
window.confirmBooks=async function(){const checks=Array.from(document.querySelectorAll('#fileList input[type=checkbox]'));const selected=[];for(const ck of checks){const i=Number(ck.dataset.i),b=state.allBooks[i];if(b)b.selected=!!ck.checked}for(const ck of checks.filter(x=>x.checked)){const i=Number(ck.dataset.i),b=state.allBooks[i],inp=document.querySelector(`#fileList [data-store-i="${i}"]`),store=String(inp?.value||'').trim();if(!store){$('confirmMsg').textContent=`请先填写店铺名称：${b.name}`;$('confirmMsg').className='hint bad';inp?.focus();return}b.storeName=store;selected.push(b)}if(!selected.length){$('confirmMsg').textContent='请至少勾选一个文件。';$('confirmMsg').className='hint bad';return}const conflicts=collectSelectedStoreConflictsV075(selected);if(conflicts.length){const currentDup=conflicts.filter(x=>x.kind==='current-duplicate'),historyConf=conflicts.filter(x=>x.kind!=='current-duplicate'),preview=historyConf.slice(0,10).map(x=>`${x.spu}：本次「${x.current}」；历史「${x.historical.join(' / ')}」`).join('\n'),dupPreview=currentDup.slice(0,5).map(x=>`${x.spu}：本次文件同时分到「${x.current}」`).join('\n'),more=conflicts.length>15?`\n…另有 ${conflicts.length-15} 条未展开`:'';let msg=`检测到店铺归属需要你确认：\n\n`;if(historyConf.length)msg+=`历史归属冲突/重复 ${historyConf.length} 个SPU：\n${preview}${historyConf.length>10?'\n…':''}\n`;if(currentDup.length)msg+=`\n当前文件互相冲突 ${currentDup.length} 个SPU：\n${dupPreview}${currentDup.length>5?'\n…':''}\n`;msg+=`${more}\n\n继续后不会立刻修改历史分类；只有成功导出时，历史归属才会按最终导出店铺更新。`;const go=await uiConfirm(msg,'检测到SPU店铺归属冲突',{confirmText:'仍按当前店铺继续',cancelText:'返回检查',tone:'warn'});if(!go){$('confirmMsg').textContent=`发现 ${conflicts.length} 条SPU店铺归属冲突，请检查橙色提示。`;$('confirmMsg').className='hint warn';return}}const newlyAdded=selected.filter(b=>b._justAdded),newSpus=new Set(newlyAdded.flatMap(b=>b.rows.map(r=>r.spu)));const keepPrices=state.prices instanceof Map?new Map(state.prices):new Map(),keepInventoryEdits=state.inventoryEdits instanceof Map?new Map(state.inventoryEdits):new Map(),keepDeleteKeys=state.deleteSpuKeys instanceof Set?new Set(state.deleteSpuKeys):new Set();const resumeSpu=state._resumeSpu||currentSpu(),resumeStore=state._resumeStore||state.currentStore;state.books=selected;state.rows=[];state.inventoryRows=[];state.spuMap=new Map();for(const b of state.books){if(!state.storeNames.includes(b.storeName))state.storeNames.push(b.storeName);for(const r of b.rows){r.store=b.storeName;state.rows.push(r);if(!state.spuMap.has(r.spu))state.spuMap.set(r.spu,[]);state.spuMap.get(r.spu).push(r);}for(const inv of b.inventoryRows||[]){inv.store=b.storeName;state.inventoryRows.push(inv)}}saveStoreNames();state.spus=Array.from(state.spuMap.keys());state.prices=new Map(Array.from(keepPrices.entries()).filter(([spu])=>state.spuMap.has(spu)));state.inventoryEdits=keepInventoryEdits;state.deleteSpuKeys=keepDeleteKeys;const stores=Array.from(new Set(selected.map(b=>b.storeName)));state.currentStore=stores.includes(resumeStore)?resumeStore:(stores[0]||'');const sf=$('storeFilter');sf.innerHTML=stores.map(x=>`<option value="${escapeHtml(x)}"></option>`).join('');sf.value=state.currentStore;let idx=resumeSpu&&state.spuMap.has(resumeSpu)&&(state.spuMap.get(resumeSpu)||[]).some(r=>r.store===state.currentStore)?state.spus.indexOf(resumeSpu):-1;if(idx<0)idx=state.spus.findIndex(s=>(state.spuMap.get(s)||[]).some(r=>r.store===state.currentStore));state.currentIndex=idx>=0?idx:0;delete state._resumeSpu;delete state._resumeStore;for(const b of state.allBooks)b._justAdded=false;$('confirmMsg').textContent=`已确认 ${selected.length} 个文件和店铺名称${conflicts.length?`；已人工确认 ${conflicts.length} 条店铺归属提示`:''}。之前已填写的价格、库存修改和整SPU删除状态不会重置。`;$('confirmMsg').className='hint ok';$('step2').classList.remove('hidden');renderSpuList();renderCurrent();updateGlobal();updateHistoryStats();updateStoreCompletionUI();renderSpecialRuleManager();refreshDesktopWorkspace(false).catch(()=>{});if(newlyAdded.length)showToast(`新增成功：已新增 ${newlyAdded.length} 个表格、${newSpus.size} 个SPU。当前店铺保持不变。`,'ok',5200)};
const btn=document.getElementById('confirmFilesBtn');if(btn)btn.onclick=window.confirmBooks;
})();
